import { createInitialState, DEFAULT_START_DATE } from './core/defaults.js';
import { loadState, saveState } from './core/storage.js';
import { arDate, hijriDate } from './core/date.js';
import { calculateEstimatedCompletionDate, calculateProgress, completeNewMemorization, generateDailyPlan, generateFullSchedule, postponeDay, recordReviewResult, reschedulePlan } from './core/scheduler.js';
import { metadataOnlyQuranProvider as quran } from './providers/QuranPageProvider.js';
import { emptyAudioProvider as audio } from './providers/AudioProvider.js';
const labels = { excellent: 'ممتاز', good: 'جيد', weak: 'ضعيف', repeat: 'يحتاج إعادة' };
let state = loadState();
let tab = 'dashboard';
const today = DEFAULT_START_DATE;
const root = document.getElementById('root');
function setState(s) { state = s; saveState(state); render(); }
function el(html) { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstElementChild; }
function bind(rootEl) { rootEl.querySelectorAll('[data-action]').forEach(b => b.onclick = () => actions[b.dataset.action]?.(b.dataset)); }
const actions = { start: () => setState({ ...state, started: true }), tab: d => { tab = d.tab || 'dashboard'; render(); }, theme: () => setState({ ...state, theme: state.theme === 'light' ? 'dark' : 'light' }), reset: () => setState(createInitialState()), postpone: () => setState(postponeDay(state, today)), complete: d => setState(completeNewMemorization(state, Number(d.page), today)), review: d => setState(recordReviewResult(state, Number(d.page), d.rating, today)), setting: d => { const input = document.querySelector(`#${d.input}`); setState(reschedulePlan(state, { [d.key]: Number(input.value) })); } };
function timer(minutes) { const id = `t${Math.random().toString(36).slice(2)}`; setTimeout(() => { let sec = minutes * 60, run = false; const n = document.getElementById(id); n.querySelector('[data-start]').addEventListener('click', () => run = !run); n.querySelector('[data-reset]').addEventListener('click', () => { sec = minutes * 60; draw(); }); function draw() { n.querySelector('b').textContent = `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`; } setInterval(() => { if (run && sec > 0) {
    sec--;
    draw();
} }, 1000); draw(); }); return `<div id="${id}" class="timer"><b></b><button data-start>بدء/إيقاف المؤقت</button><button data-reset>إعادة</button></div>`; }
function onboarding() { return `<main class="card onboarding"><h1>إعداد خطة الحفظ</h1><p>تبدأ القيم الافتراضية في 01/09/2026 من الصفحة 160، مع حفظ الأحد إلى الخميس.</p><label>كم صفحة تحفظ؟<input id="memorizedPages" type="number" value="${state.settings.memorizedPages}"></label><button data-action="setting" data-input="memorizedPages" data-key="memorizedPages">حفظ العدد</button><label>آخر صفحة وصلت إليها<input id="lastMemorizedPage" type="number" value="${state.settings.lastMemorizedPage}"></label><button data-action="setting" data-input="lastMemorizedPage" data-key="lastMemorizedPage">حفظ الصفحة</button><button class="primary" data-action="start">ابدأ الخطة</button></main>`; }
function reviewButtons(page) { return Object.keys(labels).map(r => `<button data-action="review" data-page="${page}" data-rating="${r}">${labels[r]}</button>`).join(''); }
function render() { document.documentElement.dataset.theme = state.theme; const plan = generateDailyPlan(state, today), p = calculateProgress(state.settings), completion = calculateEstimatedCompletionDate(state, today); if (!state.started) {
    root.innerHTML = onboarding();
    bind(root);
    return;
} root.innerHTML = `<header><h1>رفيق الحفظ</h1><nav>${['dashboard:الرئيسية', 'today:خطة اليوم', 'calendar:التقويم', 'progress:التقدم', 'settings:الإعدادات'].map(x => { const [a, b] = x.split(':'); return `<button class="${tab === a ? 'active' : ''}" data-action="tab" data-tab="${a}">${b}</button>`; }).join('')}</nav></header><main id="page"></main>`; const page = document.getElementById('page'); if (tab === 'dashboard')
    page.innerHTML = `<section class="grid"><article class="hero"><h2>اليوم: ${arDate(today)}</h2><p>هجري: ${hijriDate(today)}</p><h3>حفظ جديد: ${plan.newPages.length ? `صفحة ${plan.newPages.join('، ')}` : 'لا حفظ جديد'}</h3><p>${plan.suggestion ?? ''}</p>${plan.newPages.map(pg => `<button class="primary" data-action="complete" data-page="${pg}">تم حفظ صفحة ${pg}</button>`).join('')}<button data-action="postpone">تأجيل اليوم</button></article><article><h3>مراجعة المساء</h3>${plan.reviews.map(r => `<div class="item">صفحة ${r.page} — ${quran.getPage(r.page).surah}<div>${reviewButtons(r.page)}</div></div>`).join('')}</article><article><h3>التقدم</h3><div class="bar"><span style="width:${p.percent}%"></span></div><p>${p.memorizedPages} / ${state.settings.totalPages} صفحة — ${p.percent}%</p><p>الختم المتوقع: ${completion} (تقديري ويتغير بالتأجيل)</p></article><article><h3>الجلسات</h3>${timer(state.settings.morningMinutes)}${timer(state.settings.eveningMinutes)}</article></section>`; if (tab === 'today')
    page.innerHTML = `<section class="grid"><article><h2>صباحًا — حفظ جديد</h2>${plan.newPages.map(pg => { const m = quran.getPage(pg); return `<div class="item">صفحة ${pg}، سورة ${m.surah}، جزء ${m.juz}<textarea placeholder="ملاحظات شخصية"></textarea><button>بدأت</button><button data-action="complete" data-page="${pg}">تم الحفظ</button><button data-action="postpone">أحتاج إعادة</button></div>`; }).join('')}${timer(state.settings.morningMinutes)}</article><article><h2>مساءً — مراجعة</h2>${plan.reviews.map(r => `<div class="item">صفحة ${r.page}، ${quran.getPage(r.page).surah}، جزء ${quran.getPage(r.page).juz}<small>آخر مراجعة: ${r.lastReviewed ?? '—'} | آخر تقييم: ${r.lastRating ? labels[r.lastRating] : '—'} | القادمة: ${r.nextReview}</small><div>${reviewButtons(r.page)}</div></div>`).join('')}</article></section>`; if (tab === 'calendar')
    page.innerHTML = `<section><h2>التقويم</h2><div class="calendar">${generateFullSchedule(state).slice(0, 35).map(d => `<button class="${d.isMemorizationDay ? 'mem' : 'rest'}"><b>${d.date}</b><span>${d.isMemorizationDay ? 'حفظ' : 'راحة'}</span><span>${d.reviews.length} مراجعات</span></button>`).join('')}</div></section>`; if (tab === 'progress')
    page.innerHTML = `<section><h2>إحصائيات التقدم</h2><div class="stats"><b>${p.percent}%</b><span>صفحات محفوظة: ${p.memorizedPages}</span><span>متبقي: ${p.remainingPages}</span><span>أجزاء مكتملة: ${p.completedJuz}</span><span>أيام ناجحة: ${state.history.filter(h => h.type === 'memorization').length}</span><span>مراجعات: ${state.history.filter(h => h.type === 'review').length}</span><span>الختم المتوقع: ${completion}</span></div><div class="chart">${state.history.filter(h => h.type === 'memorization').slice(-20).map((_, i) => `<i style="height:${20 + i * 4}px"></i>`).join('')}</div></section>`; if (tab === 'settings')
    page.innerHTML = `<section class="grid"><article><h2>الإعدادات</h2><label>المراجعة اليومية<input id="dailyReviewPages" type="number" value="${state.settings.dailyReviewPages}"></label><button data-action="setting" data-input="dailyReviewPages" data-key="dailyReviewPages">تحديث</button><label>حفظ يومي<input id="newPagesPerDay" type="number" value="${state.settings.newPagesPerDay}"></label><button data-action="setting" data-input="newPagesPerDay" data-key="newPagesPerDay">تحديث</button><label>آخر صفحة<input id="lastMemorizedPage" type="number" value="${state.settings.lastMemorizedPage}"></label><button data-action="setting" data-input="lastMemorizedPage" data-key="lastMemorizedPage">تحديث</button><button data-action="theme">الوضع الليلي</button><button data-action="reset">إعادة الضبط</button></article><article><h3>مصادر قابلة للاستبدال</h3><p>${quran.getTrustedSourceName()}</p><p>${audio.getSourceName()}</p><p>لا يوجد نص قرآن أو صور أو صوت مدمج غير موثوق.</p></article></section>`; bind(root); }
render();
